(()=>{
"use strict";
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY=document.title.includes("Next")?"eosdo-next-base-v1":"eosdo-lite-review-v2";
const LEGACY="eosdo-lite-review-v2";
const esc=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
function get(){try{return JSON.parse(localStorage.getItem(KEY))||{}}catch{return{}}}
function put(s){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new Event("eosdo-manual-change"))}
function audit(s,a,o=""){s.audit=s.audit||[];s.audit.unshift({at:new Date().toLocaleString("ru-RU"),user:"Алексей",action:a,object:o});put(s)}
if(KEY!==LEGACY&&!localStorage.getItem(KEY)&&localStorage.getItem(LEGACY)){try{localStorage.setItem(KEY,localStorage.getItem(LEGACY))}catch{}}
const types=["Служебная записка","Распоряжение","Доверенность","Заключение о выдаче лицензии","Лицензия","Заявка на судебно-претензионный документ","Претензия","Судебное дело","Исполнительный документ","Сделка бухгалтерского архива","Документ РИД"];
const fields={
"Служебная записка":[["recipient","Адресат"],["department","Подразделение"],["docText","Текст служебной записки"]],
"Распоряжение":[["approver","Утверждающий"],["controller","Контролёр"],["docText","Текст распоряжения"]],
"Договор":[["counterparty","Контрагент"],["contractNo","Номер договора"],["contractDate","Дата договора"],["curator","Куратор"],["procurementNo","Регистрационный номер закупки"],["subject","Предмет договора"]],
"Входящий документ":[["sender","Отправитель"],["incomingNo","Номер отправителя"],["incomingDate","Дата документа"],["registrar","Регистратор"]],
"Исходящий документ":[["recipient","Получатель"],["signer","Подписант"],["docText","Текст документа"]],
"Заявка на доверенность":[["lawyer","Юрист"],["proxyFor","На кого оформляется"],["validUntil","Срок действия"]],
"Доверенность":[["proxyFor","Доверенное лицо"],["validUntil","Срок действия"],["basis","Основание"]],
"Вопрос":[["meetingOrg","Организация заседания"],["docText","Содержание вопроса"]],
"Повестка дня":[["meetingDate","Дата заседания"],["meetingOrg","Организация заседания"]],
"Протокол":[["meetingDate","Дата заседания"],["signer","Подписант"]],
"Решение":[["meetingOrg","Организация заседания"],["signer","Подписант"],["agenda","Связь с повесткой дня"]],
"Лист исполнения":[["employee","Работник, которому предоставляется доступ"],["coexecutors","Соисполнители"]],
"Заключение о выдаче лицензии":[["licenseType","Вид лицензии"],["signer","Подписант"]],
"Лицензия":[["licenseType","Вид лицензии"],["validUntil","Срок действия"]],
"Заявка на судебно-претензионный документ":[["lawyer","Юрист"],["basis","Основание"]],
"Претензия":[["counterparty","Контрагент"],["claimAmount","Сумма требований"]],
"Судебное дело":[["court","Суд"],["caseNo","Номер дела"],["lawyer","Ответственный юрист"]],
"Исполнительный документ":[["caseNo","Номер судебного дела"],["basis","Основание"]],
"Сделка бухгалтерского архива":[["basis","Документ-основание"],["operationType","Тип хозяйственной операции"],["curator","Куратор"],["primaryComplete","Комплект первичных документов"]],
"Документ РИД":[["ridType","Вид РИД"],["author","Автор/правообладатель"],["patentNo","Номер заявки/патента"]]
};
function installTypes(){let x=$("#type");if(!x)return;types.forEach(t=>{if(![...x.options].some(o=>o.value===t))x.add(new Option(t,t))})}
function renderFields(){let el=$("#typeFields"),t=$("#type")?.value;if(!el)return;el.innerHTML=(fields[t]||[]).map(([n,l])=>'<label>'+esc(l)+'<input name="x_'+n+'"></label>').join("")}
function calendar(){let el=$("#calendarWorkspace");if(!el)return;let s=get();s.workCalendar=s.workCalendar||{};let d=new Date(),y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),cells="";for(let i=0;i<first.getDay();i++)cells+="<span></span>";for(let n=1;n<=days;n++){let k=y+"-"+String(m+1).padStart(2,"0")+"-"+String(n).padStart(2,"0"),w=new Date(y,m,n).getDay(),off=k in s.workCalendar?!s.workCalendar[k]:(w===0||w===6);cells+='<button class="cal-day '+(off?"weekend":"")+'" data-cal-day="'+n+'" data-cal-key="'+k+'">'+n+"</button>"}el.innerHTML='<div class="cal-head"><b>'+first.toLocaleString("ru-RU",{month:"long",year:"numeric"})+'</b><span>Нажмите день, чтобы изменить рабочий/нерабочий</span></div><div class="cal-grid"><b>Вс</b><b>Пн</b><b>Вт</b><b>Ср</b><b>Чт</b><b>Пт</b><b>Сб</b>'+cells+"</div>"}
function assistants(){let el=$("#assistantList");if(!el)return;let s=get();s.assistants=s.assistants||[];el.innerHTML=s.assistants.map((x,i)=>'<div class="row"><div><strong>'+esc(x.person)+'</strong><span>'+esc(x.mode)+' · '+esc(x.from)+' — '+esc(x.to)+'</span></div><button data-assistant-delete="'+i+'">Удалить</button></div>').join("")||"<p>Помощники не назначены.</p>"}
function advancedSearch(){let el=$("#advancedSearch");if(!el)return;el.innerHTML='<div class="dictbar"><input id="manualSearchNo" placeholder="Номер / текст"><input id="manualSearchOwner" placeholder="Ответственный"><select id="manualSearchStatus"><option value="">Все статусы</option><option>Черновик</option><option>На согласовании</option><option>На подписании</option><option>Зарегистрирован</option><option>Закрыт</option></select><button data-manual-search>Применить</button><button data-save-search>Сохранить запрос</button><button data-reset-search>Сбросить</button></div><div id="savedSearchList"></div>';savedSearches()}
function savedSearches(){let el=$("#savedSearchList");if(!el)return;let s=get();s.savedSearches=s.savedSearches||[];el.innerHTML=s.savedSearches.map((x,i)=>'<button class="chip" data-load-search="'+i+'">'+esc(x.name)+'</button>').join("")}
function applySearch(){let s=get(),no=($("#manualSearchNo")?.value||"").toLowerCase(),owner=($("#manualSearchOwner")?.value||"").toLowerCase(),status=$("#manualSearchStatus")?.value||"",ids=new Set((s.docs||[]).filter(d=>{let hay=(d.number+" "+d.title+" "+d.type+" "+JSON.stringify(d.requisites||{})).toLowerCase();return(!no||hay.includes(no))&&(!owner||String(d.owner||"").toLowerCase().includes(owner))&&(!status||d.status===status)}).map(d=>String(d.id)));$$('#docTable tr[data-doc]').forEach(r=>r.style.display=ids.has(String(r.dataset.doc))?"":"none")}
function approvalQueues(){let el=$("#queueWorkspace");if(!el)return;let d=get().docs||[],a=d.filter(x=>x.status==="На согласовании"),p=d.filter(x=>x.status==="На подписании");el.innerHTML='<div class="grid"><section><h3>На согласовании</h3>'+(a.map(x=>'<div class="row" data-doc="'+x.id+'"><strong>'+esc(x.number)+'</strong><span>'+esc(x.title)+'</span></div>').join("")||"<p>Очередь пуста</p>")+'</section><section><h3>На подписании</h3>'+(p.map(x=>'<div class="row" data-doc="'+x.id+'"><strong>'+esc(x.number)+'</strong><span>'+esc(x.title)+'</span></div>').join("")||"<p>Очередь пуста</p>")+"</section></div>"}
function archiveActs(){let el=$("#archiveActs");if(!el)return;let a=get().archiveActs||[];el.innerHTML=a.map(x=>'<div class="row"><div><strong>'+esc(x.kind)+'</strong><span>'+esc(x.at)+'</span></div><span class="badge reg">'+esc(x.status)+'</span></div>').join("")||"<p>Описи и акты ещё не формировались.</p>"}
function medoDetails(){let el=$("#medoDetails");if(!el)return;let m=get().medo||[];el.innerHTML='<h3>Операции МЭДО</h3>'+(m.map(x=>'<div class="row"><div><strong>'+esc(x.number)+'</strong><span>'+esc(x.sender||"")+' · '+esc(x.status)+'</span></div>'+(String(x.direction).toLowerCase().includes("incoming")||String(x.direction).toLowerCase().includes("вход")?'<button data-medo-register="'+x.id+'">Зарегистрировать</button><button data-medo-reject="'+x.id+'">Отказ</button>':'<button data-medo-status="'+x.id+'">Статус доставки</button>')+"</div>").join("")||"<p>Пакетов нет.</p>")}
function installComplianceStatus(){let el=$("#diagnosticsResult");if(!el)return;let required=["auditView","docsView","calendarView","delegationView","tasksView","ordersView","controlView","journalsView","archiveView","orgarchiveView","reserveView","dictView","corpView","reportsView","medoView","issuedView","enterpriseView","templatesView","queuesView"],missing=required.filter(id=>!document.getElementById(id));let typesOk=["Служебная записка","Договор","Доверенность","Вопрос","Повестка дня","Протокол","Решение","Лист исполнения","Лицензия","Претензия","Судебное дело","Исполнительный документ","Сделка бухгалтерского архива","Документ РИД"].every(t=>[...($("#type")?.options||[])].some(o=>o.value===t));el.insertAdjacentHTML("beforeend",'<div class="row"><div><strong>Покрытие руководства ЕОСДО 2.0</strong><span>'+(missing.length?"Нет разделов: "+missing.join(", "):typesOk?"Основные разделы и типы документов присутствуют.":"Не все типы документов доступны.")+'</span></div><span class="badge '+(!missing.length&&typesOk?"reg":"rework")+'">'+(!missing.length&&typesOk?"100% UI":"CHECK")+"</span></div>")}
function refresh(){installTypes();renderFields();calendar();assistants();approvalQueues();archiveActs();medoDetails()}
document.addEventListener("DOMContentLoaded",()=>{refresh();advancedSearch();installComplianceStatus()});
document.addEventListener("change",e=>{if(e.target.id==="type")renderFields()});
document.addEventListener("submit",e=>{if(e.target.id!=="createForm")return;let fd=new FormData(e.target),extra={},files=[];for(const [k,v] of fd){if(k.startsWith("x_"))extra[k.slice(2)]=v;if(k==="files"&&v?.name)files.push({name:v.name,size:v.size,type:v.type})}setTimeout(()=>{let s=get(),d=s.docs?.[0];if(d){d.requisites={...(d.requisites||{}),...extra};d.files=files;put(s)}},50)},true);
document.addEventListener("click",e=>{
 let cd=e.target.closest("[data-cal-key]");if(cd){let s=get(),k=cd.dataset.calKey,w=new Date(k+"T12:00:00").getDay(),defaultWork=!(w===0||w===6),current=k in(s.workCalendar||{})?s.workCalendar[k]:defaultWork;s.workCalendar=s.workCalendar||{};s.workCalendar[k]=!current;audit(s,"Изменён календарь рабочих дней",k);calendar();return}
 if(e.target.closest("[data-manual-search]")){applySearch();return}
 if(e.target.closest("[data-reset-search]")){$("#manualSearchNo").value="";$("#manualSearchOwner").value="";$("#manualSearchStatus").value="";$$('#docTable tr[data-doc]').forEach(r=>r.style.display="");return}
 if(e.target.closest("[data-save-search]")){let s=get();s.savedSearches=s.savedSearches||[];let name=prompt("Название поискового запроса","Мой поиск");if(!name)return;s.savedSearches.push({name,no:$("#manualSearchNo")?.value||"",owner:$("#manualSearchOwner")?.value||"",status:$("#manualSearchStatus")?.value||""});put(s);savedSearches();return}
 let ls=e.target.closest("[data-load-search]");if(ls){let x=(get().savedSearches||[])[+ls.dataset.loadSearch];if(x){$("#manualSearchNo").value=x.no;$("#manualSearchOwner").value=x.owner;$("#manualSearchStatus").value=x.status;applySearch()}return}
 if(e.target.closest("#helpBtn")){alert("ЕОСДО 2.0: создание проекта из шаблона → согласование → подписание/утверждение → регистрация → исполнение/архив.");return}
 if(e.target.closest("#supportBtn")){let s=get(),t=prompt("Опишите обращение в техподдержку");if(t){s.supportTickets=s.supportTickets||[];s.supportTickets.unshift({text:t,at:new Date().toLocaleString("ru-RU"),status:"Создано"});audit(s,"Создано обращение в техподдержку",t)}return}
 if(e.target.closest("#logoutBtn")){sessionStorage.removeItem("eosdo-session");alert("Демо: сеанс завершён. Серверная IAM-авторизация не подключена.");return}
 if(e.target.closest("[data-add-assistant]")){let s=get();s.assistants=s.assistants||[];let p=prompt("Помощник");if(!p)return;let mode=prompt("Режим: параллельный или последовательный","параллельный")||"параллельный";s.assistants.push({person:p,mode,from:new Date().toLocaleDateString("ru-RU"),to:"бессрочно"});audit(s,"Назначен помощник",p);assistants();return}
 let ad=e.target.closest("[data-assistant-delete]");if(ad){let s=get(),x=(s.assistants||[]).splice(+ad.dataset.assistantDelete,1)[0];audit(s,"Удалён помощник",x?.person||"");assistants();return}
 if(e.target.closest("[data-add-substitution]")){$("#substitute")?.click();return}
 if(e.target.closest("[data-archive-inventory]")||e.target.closest("[data-archive-transfer-act]")||e.target.closest("[data-archive-destroy-act]")){let s=get();s.archiveActs=s.archiveActs||[];let kind=e.target.closest("[data-archive-inventory]")?"Опись дел":e.target.closest("[data-archive-transfer-act]")?"Акт передачи":"Акт на уничтожение";s.archiveActs.unshift({kind,at:new Date().toLocaleDateString("ru-RU"),status:"Сформирован"});audit(s,"Сформирован архивный документ",kind);archiveActs();return}
 if(e.target.closest("[data-medo-incoming]")){let s=get(),sender=prompt("Отправитель входящего пакета МЭДО","Организация");if(!sender)return;s.medo=s.medo||[];s.medo.unshift({id:"m"+Date.now(),direction:"incoming",number:"МЭДО-"+Date.now().toString().slice(-6),sender,recipient:"АО «Организация»",status:"Получен",history:["Получен входящий пакет"]});audit(s,"Получен пакет МЭДО",sender);medoDetails();return}
 let mr=e.target.closest("[data-medo-register]");if(mr){let s=get(),x=(s.medo||[]).find(v=>String(v.id)===mr.dataset.medoRegister);if(x){x.status="Зарегистрирован";x.history=x.history||[];x.history.unshift("Входящий документ зарегистрирован");audit(s,"Зарегистрирован входящий МЭДО",x.number);medoDetails()}return}
 let mj=e.target.closest("[data-medo-reject]");if(mj){let reason=prompt("Причина отказа в регистрации");if(!reason)return;let comment=prompt("Комментарий","")||"",s=get(),x=(s.medo||[]).find(v=>String(v.id)===mj.dataset.medoReject);if(x){x.status="Отказ в регистрации";x.rejectReason=reason;x.rejectComment=comment;x.history=x.history||[];x.history.unshift("Отказ: "+reason);audit(s,"Отказ в регистрации МЭДО",x.number);medoDetails()}return}
 let ms=e.target.closest("[data-medo-status]");if(ms){let s=get(),x=(s.medo||[]).find(v=>String(v.id)===ms.dataset.medoStatus);if(x){alert("Статус доставки: "+x.status+"\n"+(x.history||[]).join("\n"))}return}
});
window.addEventListener("eosdo-manual-change",()=>{assistants();approvalQueues();archiveActs();medoDetails()});
})();